for q in ['hyperbolic generative recommendation semantic IDs','hyperbolic sequential recommendation next item','generative semantic IDs recommendation']:
 u='https://api.openalex.org/works'; r=requests.get(u,params={'search':q,'per-page':10},timeout=25); print('\nQUERY',q,r.status_code)
 for x in r.json().get('results',[]): print(x.get('title'),x.get('doi'),x.get('publication_year'),x.get('open_access',{}).get('oa_url'))
