{"command":"python - <<'PY'
import requests
qs=['HypRQ-VAE Hyperbolic Item Indexing for Long-Tail-Aware Generative Recommender Systems','TIGER Recommender system Generative retrieval semantic IDs','generative recommendation hyperbolic semantic item indexing']
for q in qs:
 j=requests.get('https://api.openalex.org/works',params={'search':q,'per-page':5},timeout=25).json()
 for x in j['results']:
  print('\n',x['title'],x.get('doi'),x['publication_year'],x.get('open_access',{}).get('oa_url'))
  inv=x.get('abstract_inverted_index') or {}; words=['']*(max([p for ps in inv.values() for p in ps],default=-1)+1)
  for w,ps in inv.items():
   for p in ps: words[p]=w
  print(' '.join(words)[:1700])
PY","timeout":120000}

