python - <<'PY'
import requests,re
from bs4 import BeautifulSoup
for aid in ['2609.03369','2305.05065','2104.07323']:
 u='https://arxiv.org/html/'+aid;r=requests.get(u,timeout=30);s=BeautifulSoup(r.text,'html.parser'); t=' '.join(s.stripped_strings)
 print('\n',aid,len(t),t[:300]);
 for term in ['hyperbolic','next item','semantic ID','next-item']:
  print(term, [m.start() for m in re.finditer(term,t,re.I)][:5])
PY

